{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Codeine, a close structural analogue sharing the methoxy-substituted morphinan core, showed about 90% systemic availability after oral administration in healthy volunteers, supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Morphine, a related morphinan alkaloid, had an absolute oral bioavailability of 32% in healthy volunteers, still above the 20% threshold and supportive of high oral availability for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Noscapine, another related alkaloid, showed an absolute oral bioavailability of 30% in human volunteers, supporting the pattern that these alkaloids generally exceed the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is galantamine, a morphinan-related alkaloid. The closest experimental analogues (codeine, morphine, noscapine) all show oral bioavailability at or above 20%, with codeine, which shares the methoxy and N-methyl features, showing 42-90%. Low-bioavailability records come from structurally distant scaffolds (tetrabenazine, trospium) and do not transfer. Therefore F >= 20% is supported.",
  "evidence_gaps": [
    "No direct galantamine bioavailability record is present in the provided evidence; the prediction relies on close analogues.",
    "Fasted-state conditions are not explicitly matched in most analogue records; codeine and morphine data are mostly unspecified or mixed fed/fasted.",
    "Tetrabenazine low-bioavailability records are not transferable due to a different scaffold and extensive first-pass metabolism."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

